**packages/plugin-grid/src/ObjectGrid.tsx:475**
* The column hiding logic only applies the `hidden sm:table-cell` className to non-essential columns when processing ListColumn format. However, columns in other formats (already in data-table format, string array format, or auto-generated from objectSchema) do not receive mobile-responsive hiding. This creates an inconsistent mobile experience where some grids will hide columns on mobile and others won't, depending on how the schema is defined.
```
              // Determine if column should be hidden on mobile
              const isEssential = colIndex === 0 || (col as any).essential === true;

              return {
                header,
                accessorKey: col.field,
                ...(!isEssential && { className: 'hidden sm:table-cell' }),
                ...(col.width && { width: col.width }),
                ...(inferredAlign && { align: inferredAlign }),
                sortable: col.sortable !== false,
                ...(col.resizable !== undefined && { resizable: col.resizable }),
                ...(col.wrap !== undefined && { wrap: col.wrap }),
                ...(cellRenderer && { cell: cellRenderer }),
              };
            });
        }
      }

      // String array format - filter out invalid entries
      return (cols as string[])
        .filter((fieldName) => typeof fieldName === 'string' && fieldName.trim().length > 0)
        .map((fieldName) => {
          const fieldLabel = objectSchema?.fields?.[fieldName]?.label;
          return {
            header: fieldLabel || fieldName.charAt(0).toUpperCase() + fieldName.slice(1).replace(/_/g, ' '),
            accessorKey: fieldName,
          };
        });
    }

    // Legacy support: use 'fields' if columns not provided
    if (hasInlineData) {
      const inlineData = dataConfig?.provider === 'value' ? dataConfig.items as any[] : [];
      if (inlineData.length > 0) {
        const fieldsToShow = schemaFields || Object.keys(inlineData[0]);
        return fieldsToShow.map((fieldName) => ({
          header: fieldName.charAt(0).toUpperCase() + fieldName.slice(1).replace(/_/g, ' '),
          accessorKey: fieldName,
        }));
      }
    }

    if (!objectSchema) return [];

    const generatedColumns: any[] = [];
    const fieldsToShow = schemaFields || Object.keys(objectSchema.fields || {});

    fieldsToShow.forEach((fieldName) => {
      const field = objectSchema.fields?.[fieldName];
      if (!field) return;

      if (field.permissions && field.permissions.read === false) return;

      const CellRenderer = getCellRenderer(field.type);
      const numericTypes = ['number', 'currency', 'percent'];
      generatedColumns.push({
        header: field.label || fieldName,
        accessorKey: fieldName,
        ...(numericTypes.includes(field.type) && { align: 'right' }),
        cell: (value: any) => <CellRenderer value={value} field={field} />,
        sortable: field.sortable !== false,
      });
    });

    return generatedColumns;
```
**packages/plugin-detail/src/DetailSection.tsx:122**
* The entire field container becomes clickable and is marked as a button role, but the nested Button inside also has click handlers. This creates a nested interactive element which is an accessibility anti-pattern. When the user clicks the button, both `onClick` handlers will fire (the outer div and the button itself), even though `stopPropagation` is called. Consider either removing the button role and tabIndex from the outer div when a button is present, or restructuring the component to avoid nested interactive elements.
```
        <div
          className={cn(
            "flex items-start justify-between gap-2 min-h-[44px] sm:min-h-0 rounded-md",
            canCopy && "cursor-pointer active:bg-muted/60 transition-colors"
          )}
          onClick={canCopy ? () => handleCopyField(field.name, value) : undefined}
          onKeyDown={canCopy ? (e: React.KeyboardEvent) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              handleCopyField(field.name, value);
            }
          } : undefined}
          role={canCopy ? "button" : undefined}
          tabIndex={canCopy ? 0 : undefined}
        >
          <div className="text-sm flex-1 break-words py-1">
            {displayValue}
          </div>
          {canCopy && (
            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity shrink-0"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleCopyField(field.name, value);
                    }}
                  >
                    {isCopied ? (
                      <Check className="h-3 w-3 text-green-600" />
                    ) : (
                      <Copy className="h-3 w-3" />
                    )}
                  </Button>
                </TooltipTrigger>
                <TooltipContent>
                  {isCopied ? 'Copied!' : 'Copy to clipboard'}
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>
          )}
        </div>
```
